using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "EffectCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/EffectCustomDescription", order = 0)]
public class EffectCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string text = "";
		if ((bool)battleAction.TargetData)
		{
			text = battleAction.TargetData.TargetEffectID;
			if (amountModified == "-4")
			{
				text += "FutureLatinLanguages";
			}
		}
		else
		{
			text = "AnyEffect";
		}
		string localizedString = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(text);
		if (int.Parse(amountModified) >= EffectsValues.INFINITY)
		{
			return Smart.Format(ReplacePreposition(localizedString), Smart.Format(base.localizationManager.GetLocalizedInfinity(), battleAction.GetActionNameForDescription()));
		}
		if (amountModified == "-1")
		{
			return Smart.Format(localizedString.Replace("{0}", ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedX()).Replace("{1}", "{0}"), battleAction.GetActionNameForDescription());
		}
		if (amountModified == EffectsValues.NO_VALUE_STRING || amountModified == "-4")
		{
			return Smart.Format(ReplacePreposition(localizedString), battleAction.GetActionNameForDescription());
		}
		if (amountModified == "-3")
		{
			return Smart.Format(localizedString, "{0}", battleAction.GetActionNameForDescription());
		}
		return Smart.Format(localizedString, amountModified, battleAction.GetActionNameForDescription());
	}

	public string ReplacePreposition(string text)
	{
		if (LanguagesIndexes.CurrentLanguageIndex == 1 || LanguagesIndexes.CurrentLanguageIndex == 9)
		{
			return text.Replace(" de {1}", "");
		}
		if (LanguagesIndexes.CurrentLanguageIndex == 4)
		{
			return text.Replace("{1} x\u00a0", "").Replace(" x\u00a0{1}", "");
		}
		if (LanguagesIndexes.IsCurrentLanguageRussian())
		{
			return text.Replace("{1} ×", "").Replace("{1}\u00a0×", "");
		}
		if (LanguagesIndexes.IsCurrentLanguageTraditionalChinese())
		{
			return text.Replace("點{1}", "").Replace("個{1}", "");
		}
		return text.Replace(" {1}", "").Replace("{1}", "");
	}
}
